$('#findings').innerHTML=[['LARGEST ENERGY CONSUMER',val(demand[0],'total_energy_consumption_exajoules',' EJ'),`${demand[0].country} leads the supplied sample.`,demand[0].total_energy_consumption_year],['HIGHEST BUSINESS PRICE',val(priced[0],'business_price_usd_per_kwh','$',3).replace('$','')+' $/kWh',`${priced[0].country} · ${priced.length} available observations.`,priced[0].price_period],['LARGEST NET IMPORTER',val(trade[0],'total_energy_net_imports_ej',' EJ'),`${trade[0].country} · total energy net imports.`,trade[0].total_energy_production_trade_year],['LARGEST NET EXPORTER',fmt(-num(trade.at(-1),'total_energy_net_imports_ej'))+' EJ',`${trade.at(-1).country} · net export magnitude.`,trade.at(-1).total_energy_production_trade_year]].map(x=>`<article class="finding"><div class="small">${x[0]}</div><strong>${x[1]}</strong><p>${x[2]}</p><span class="small">${x[3]} · observed in dataset</span></article>`).join('');
function picker(){ $('#compareSummary').textContent=`${comparison.length} selected · ${comparison.join(', ')||'choose countries'}`;$('#checks').innerHTML=DATA.map(r=>`<label><input type="checkbox" value="${esc(r.country)}" ${comparison.includes(r.country)?'checked':''}>${esc(r.country)}</label>`).join('');$('#checks').onchange=e=>{const c=e.target.value;if(e.target.checked&&comparison.length>=4){e.target.checked=false;$('#limit').textContent='Choose at most four countries. Remove one to add another.';return}comparison=e.target.checked?[...comparison,c]:comparison.filter(x=>x!==c);$('#limit').textContent='';picker();render()}}
function spotlight(c){selected=c;$('#country').value=c;render()}
function mark(r,text,cls='',style=''){return `class="${cls}" style="${style}" tabindex="0" role="button" data-country="${esc(r.country)}" data-tip="${esc(text)}" aria-label="${esc(text)}"`}
function country(r){return `<button class="country-button" data-country="${esc(r.country)}">${esc(r.country)}</button>`}
function sorted(rows,i,key){let s=$('#sort'+i).value;return [...rows].sort((a,b)=>{if(s==='name')return a.country.localeCompare(b.country);const aa=key(a,s),bb=key(b,s);if(aa==null)return 1;if(bb==null)return -1;return s==='asc'?aa-bb:bb-aa})}
function render(){const rows=$('#scope').value==='compare'?DATA.filter(r=>comparison.includes(r.country)):DATA;profile();for(let i=0;i<5;i++){if(!rows.length){$('#chart'+i).innerHTML='<p>Select at least one comparison country.</p>';continue}if(i===2||i===3){const prefix=i===2?'electricity_generation_':'primary_energy_consumption_',cats=i===2?electricity:primary;const rr=sorted(rows,i,(r,s)=>s==='ws'?(num(r,prefix+'wind_pct')==null||num(r,prefix+'solar_pct')==null?null:num(r,prefix+'wind_pct')+num(r,prefix+'solar_pct')):num(r,prefix+'coal_pct'));$('#chart'+i).innerHTML='<div class="axis-caption"><span>0%</span><span>100%</span></div>'+rr.map(r=>`<div class="bar-row stack-row ${r.country===selected?'selected':''}">${country(r)}<div class="stack">${cats.some(c=>num(r,prefix+c[1]+'_pct')==null)?'Unavailable':cats.map((c,j)=>`<div ${mark(r,`${r.country}\n${c[0]}: ${r[prefix+c[1]+'_pct']}% · ${r.mix_year}\n${i===2?r.electricity_mix_basis:r.primary_energy_mix_basis}`,'segment',`width:${num(r,prefix+c[1]+'_pct')}%;background:${colors[j]}`)}></div>`).join('')}</div></div>`).join('')+`<div class="legend">${cats.map((c,j)=>`<span><i style="background:${colors[j]}"></i>${c[0]}</span>`).join('')}</div><p class="small">${[...new Set(rows.map(r=>r.mix_year))].join(', ')} · supplied shares, rounded; totals may differ slightly from 100%.</p>`;continue}
 const key=i===0?'total_energy_consumption_exajoules':i===1?'business_price_usd_per_kwh':'total_energy_net_imports_ej', rr=sorted(rows,i,r=>num(r,key)),max=Math.max(...rows.map(r=>Math.abs(num(r,key)??0)),1e-9);$('#chart'+i).innerHTML=(i===4?'<div class="axis-caption"><span>← Net exporters</span><span>Net importers →</span></div>':'')+rr.map(r=>{const v=num(r,key),year=i===0?r.total_energy_consumption_year:i===1?r.price_period:r.total_energy_production_trade_year;const tip=`${r.country}\n${v==null?'Unavailable':r[key]} ${i===1?'USD/kWh':'EJ'} · ${year}\n`+(i===0?'Total national energy consumption.':i===1?`Local price: ${r.business_price_local_currency_per_kwh||'Unavailable'} ${r.local_currency}/kWh\n${r.price_basis}\n${r.notes}`:`Domestic production: ${r.total_energy_domestic_production_ej} EJ\nGross imports: ${r.total_energy_gross_imports_ej} EJ\nGross exports: ${r.total_energy_gross_exports_ej} EJ\nNet imports = gross imports − gross exports.`);return `<div class="bar-row ${r.country===selected?'selected':''}">${country(r)}<div ${mark(r,tip,'bar-track '+(i===4?'trade-track':''))}>${v==null?'':i===4?`<div class="trade-bar ${v<0?'export':''}" style="left:${v<0?50-Math.abs(v)/max*50:50}%;width:${Math.abs(v)/max*50}%"></div>`:`<div class="bar" style="width:${v/max*100}%"></div>`}</div><span class="value">${v==null?'N/A':fmt(v,i===1?3:2)}</span></div>`}).join('')+`<p class="small">${[...new Set(rows.map(r=>i===0?r.total_energy_consumption_year:i===1?r.price_period:r.total_energy_production_trade_year))].join(', ')} · ${i===1?'Missing prices are unavailable; see each bar for its period.':'Countries in the supplied sample only.'}</p>`}
scatter(rows);table(rows);}
function scatter(rows){const valid=rows.filter(r=>num(r,'business_price_usd_per_kwh')!=null&&fossil(r)!=null&&num(r,'electricity_domestic_generation_twh')!=null),maxPrice=Math.max(...DATA.map(r=>num(r,'business_price_usd_per_kwh')||0)) *1.12,maxGen=Math.max(...DATA.map(r=>num(r,'electricity_domestic_generation_twh')||0));$('#chart5').innerHTML=`<svg viewBox="0 0 560 390" role="group" aria-label="Business electricity price versus fossil generation share"><text x="52" y="16">Fossil generation share (%)</text>${[0,25,50,75,100].map(v=>`<line x1="52" x2="525" y1="${335-v*2.8}" y2="${335-v*2.8}" stroke="#dce4ea"/><text x="16" y="${339-v*2.8}">${v}</text>`).join('')}${[0,.1,.2,.3,.4,.5].filter(v=>v<=maxPrice).map(v=>`<text x="${52+v/maxPrice*473}" y="356" text-anchor="middle">${v.toFixed(1)}</text>`).join('')}<text x="280" y="384" text-anchor="middle">Business electricity price (USD/kWh)</text>${valid.map(r=>`<circle cx="${52+num(r,'business_price_usd_per_kwh')/maxPrice*473}" cy="${335-fossil(r)*2.8}" r="${Math.sqrt(num(r,'electricity_domestic_generation_twh')/maxGen)*29}" fill="${r.country===selected?'#dba63d':'#326991'}" fill-opacity=".65" ${mark(r,`${r.country}\nBusiness electricity: ${r.business_price_usd_per_kwh} USD/kWh · ${r.price_period}\nFossil generation: ${fmt(fossil(r),2)}% · ${r.mix_year}\nDomestic generation: ${r.electricity_domestic_generation_twh} TWh · ${r.electricity_production_trade_year}\nBubble area proportional to TWh.`,r.country===selected?'selected':'')}></circle>`).join('')}</svg><p class="small">${valid.length} countries plotted; ${rows.length-valid.length} excluded for missing inputs. Mix ${[...new Set(valid.map(r=>r.mix_year))].join(', ')} · volumes ${[...new Set(valid.map(r=>r.electricity_production_trade_year))].join(', ')}. Price periods shown in tooltips. Largest bubble = ${fmt(maxGen)} TWh.</p>`}
function profile(){const r=DATA.find(r=>r.country===selected);$('#profile').innerHTML=`<h2>${esc(r.country)} <span class="small">/ COUNTRY SPOTLIGHT</span></h2><div class="profile-grid"><div><span class="small">Business electricity · ${r.price_period}</span><strong>${val(r,'business_price_usd_per_kwh',' $/kWh',3)}</strong><span class="small">${val(r,'business_price_local_currency_per_kwh',' '+r.local_currency+'/kWh',3)}</span></div><div><span class="small">Energy consumption · ${r.total_energy_consumption_year}</span><strong>${val(r,'total_energy_consumption_exajoules',' EJ')}</strong><span class="small">Total national energy use</span></div><div><span class="small">Domestic energy production · ${r.total_energy_production_trade_year}</span><strong>${val(r,'total_energy_domestic_production_ej',' EJ')}</strong><span class="small">Includes output that may be exported</span></div><div><span class="small">Net energy imports · ${r.total_energy_production_trade_year}</span><strong>${val(r,'total_energy_net_imports_ej',' EJ')}</strong><span class="small">Negative = net exports</span></div></div><details><summary>Generation mix, household prices &amp; trade detail</summary><p>Electricity generation mix (${r.mix_year}): ${electricity.map(c=>c[0]+' '+val(r,'electricity_generation_'+c[1]+'_pct','%',2)).join(' · ')}.</p><p>Household electricity (${r.price_period}): ${val(r,'household_price_usd_per_kwh',' USD/kWh',3)} / ${val(r,'household_price_local_currency_per_kwh',' '+r.local_currency+'/kWh',3)}.</p><p>Total energy (${r.total_energy_production_trade_year}): gross imports ${val(r,'total_energy_gross_imports_ej',' EJ',6)}; gross exports ${val(r,'total_energy_gross_exports_ej',' EJ',6)}.</p><p>Electricity (${r.electricity_production_trade_year}): domestic generation ${val(r,'electricity_domestic_generation_twh',' TWh',6)}; gross imports ${val(r,'electricity_gross_imports_twh',' TWh',6)}; gross exports ${val(r,'electricity_gross_exports_twh',' TWh',6)}; net imports ${val(r,'electricity_net_imports_twh',' TWh',6)}.</p></details>`}
function table(rows){const filtered=rows.filter(r=>r.country.toLowerCase().includes($('#search').value.toLowerCase()));$('#tbody').innerHTML=filtered.map(r=>`<tr class="${r.country===selected?'selected':''}"><td>${country(r)}</td><td>${val(r,'total_energy_consumption_exajoules')} <span class="small">(${r.total_energy_consumption_year})</span></td><td>${val(r,'business_price_usd_per_kwh','',3)}</td><td>${r.price_period}</td><td>${val(r,'total_energy_net_imports_ej','',6)}</td><td>${r.total_energy_production_trade_year}</td></tr>`).join('');$('#tableCount').textContent=filtered.length+' countries shown · Table follows chart scope. Download includes all source columns and countries.'}
$('#sources').innerHTML=DATA.map(r=>`<article><b>${esc(r.country)}</b><p>${[['Prices','price_source_url'],['Consumption','consumption_source_url'],['Mix data','mix_source_url'],['Mix definitions','mix_definitions_url'],['Energy trade','total_energy_production_trade_source_url'],['Electricity trade','electricity_production_trade_source_url']].filter(x=>/^https?:\/\//.test(r[x[1]])).map(x=>`<a target="_blank" rel="noopener noreferrer" href="${esc(r[x[1]])}">${x[0]} ↗</a>`).join('')}</p><p>Accessed: ${esc(r.accessed_date)}. ${esc(r.notes)}</p><p>${esc(r.mix_notes)}</p><p>${esc(r.production_trade_notes)}</p></article>`).join('');
$('#country').onchange=e=>spotlight(e.target.value);$('#scope').onchange=render;$('#search').oninput=render;for(let i=0;i<5;i++)$('#sort'+i).onchange=render;$('#reset').onclick=()=>{selected='China';comparison=[...defaults];$('#country').value=selected;$('#scope').value='all';$('#search').value='';$('#limit').textContent='';for(let i=0;i<5;i++)$('#sort'+i).selectedIndex=0;picker();render()};
document.addEventListener('click',e=>{const el=e.target.closest('[data-country]');if(el)spotlight(el.dataset.country)});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#tooltip').hidden=true;if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-tip]')){e.preventDefault();spotlight(e.target.dataset.country)}});
function showTip(el,x,y){if(!el)return;const t=$('#tooltip');t.textContent=el.dataset.tip;t.hidden=false;t.style.left=Math.max(8,Math.min(x+14,innerWidth-t.offsetWidth-12))+'px';t.style.top=Math.max(8,Math.min(y+14,innerHeight-t.offsetHeight-12))+'px'}
document.addEventListener('pointerover',e=>showTip(e.target.closest('[data-tip]'),e.clientX,e.clientY));document.addEventListener('pointerout',e=>{if(e.target.closest('[data-tip]'))$('#tooltip').hidden=true});document.addEventListener('focusin',e=>{const el=e.target.closest('[data-tip]');if(el){const r=el.getBoundingClientRect();showTip(el,r.left,r.bottom)}});document.addEventListener('focusout',()=>$('#tooltip').hidden=true);
