if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_energy_comparison',description:'Select a country spotlight and up to four comparison countries in this briefing.',inputSchema:{type:'object',properties:{country:{type:'string',enum:DATA.map(r=>r.country)},comparison:{type:'array',items:{type:'string',enum:DATA.map(r=>r.country)},minItems:1,maxItems:4,uniqueItems:true}},required:['country','comparison'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!DATA.some(r=>r.country===input.country)||!Array.isArray(input.comparison)||input.comparison.length<1||input.comparison.length>4||new Set(input.comparison).size!==input.comparison.length||input.comparison.some(c=>!DATA.some(r=>r.country===c)))throw new Error('Choose a valid country and one to four unique comparison countries.');comparison=[...input.comparison];$('#scope').value='compare';picker();spotlight(input.country);return{country:selected,comparison:[...comparison],scope:'compare'}}})).catch(()=>{})}catch{}}
